package com.justnpcx.starveil.core.kernel.ruleset

import java.io.File
import org.junit.Assert.assertEquals
import org.junit.Assert.assertFalse
import org.junit.Assert.assertTrue
import org.junit.Assume.assumeTrue
import org.junit.Test

/**
 * The fixture is 94 bytes and was generated by the same algorithm sing-box
 * writes with: two exact names, one suffix and one keyword. It pins the parts
 * that are easy to get subtly wrong — the trie walk, the marker bytes and the
 * zlib envelope — without needing a network in CI.
 */
class SrsTest {

    private fun fixture(name: String): ByteArray =
        javaClass.getResourceAsStream("/$name")!!.readBytes()

    @Test
    fun `exact names, suffixes and keywords come back apart`() {
        val set = Srs.read(fixture("domain-small.srs"))

        assertEquals(3, set.version)
        assertEquals(1, set.rules.size)
        val rule = set.rules.single()
        assertEquals(listOf("ads.example.org", "exact.example.com"), rule.exactDomains)
        assertEquals(listOf("suffix.example.net"), rule.domainSuffixes)
        assertEquals(listOf("adserver"), rule.domainKeywords)
        assertFalse(rule.invert)
    }

    @Test
    fun `a file that is not a rule set is rejected by its header`() {
        val thrown = runCatching { Srs.read("not a rule set".toByteArray()) }
            .exceptionOrNull()
        assertTrue(thrown is SrsFormatException)
        assertTrue(thrown!!.message!!.contains("not a rule-set file"))
    }

    /**
     * The real thing, when one is on disk: @@SRS_SAMPLE=/path/to/x.srs ./gradlew
     * :core:kernel:testDebugUnitTest --tests "*SrsTest*"@@. Skipped otherwise,
     * because CI has no business downloading a rule set to run a unit test.
     */
    @Test
    fun `a real rule set parses end to end`() {
        val path = System.getenv("SRS_SAMPLE")
        assumeTrue("SRS_SAMPLE is not set", path != null)
        val set = Srs.read(File(path!!).readBytes())

        val exact = set.exactDomains
        val suffixes = set.domainSuffixes
        val keywords = set.domainKeywords
        println(
            "SRS_SAMPLE: ${File(path).name} version=${set.version} rules=${set.rules.size} " +
                "exact=${exact.size} suffixes=${suffixes.size} keywords=${keywords.size}",
        )
        assertTrue("no exact names", exact.isNotEmpty())
        assertTrue("no suffixes", suffixes.isNotEmpty())
        if (File(path).name.contains("ads")) {
            assertTrue(
                "doubleclick.net is not in the ad set",
                exact.any { it == "doubleclick.net" } ||
                    suffixes.any { it == "doubleclick.net" || it == ".doubleclick.net" },
            )
        }
    }
}

